package oauthtest_test

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"net/url"
	"testing"

	"github.com/mudler/LocalAI/core/services/studio/oauthtoken"
	"github.com/mudler/LocalAI/core/services/studio/oauthtoken/oauthtest"
	"github.com/mudler/LocalAI/pkg/addons/contract"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestOAuthTest(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "oauthtest suite")
}

var _ = Describe("the fake OAuth service", func() {
	ctx := context.Background()
	const host = "login.provider-a.example.test"
	desc := func(clientAuth string) contract.OAuthDescriptor {
		return contract.OAuthDescriptor{AuthorizeURL: "https://" + host + "/authorize", TokenURL: "https://" + host + "/token", RevokeURL: "https://" + host + "/revoke",
			Hosts: []string{host}, Scopes: contract.OAuthScopes{Required: []string{"read"}}, PKCE: contract.OAuthPKCES256, ClientAuth: clientAuth}
	}
	// login gets a code for verifier through the authorize endpoint.
	login := func(n *oauthtest.Network, verifier string) string {
		sum := sha256.Sum256([]byte(verifier))
		q := url.Values{"response_type": {"code"}, "client_id": {"client-a"}, "redirect_uri": {"https://localai.example.test/cb"}, "scope": {"read"},
			"state": {"s"}, "code_challenge": {base64.RawURLEncoding.EncodeToString(sum[:])}, "code_challenge_method": {"S256"}}
		back, err := n.Authorize(ctx, "https://"+host+"/authorize?"+q.Encode())
		Expect(err).NotTo(HaveOccurred())
		Expect(back.Query().Get("state")).To(Equal("s"))
		return back.Query().Get("code")
	}

	It("serves the authorize endpoint at the path the config names", func() {
		p := oauthtest.New(oauthtest.Config{Host: host, ClientID: "client-a", ClientSecret: "secret", ClientAuth: contract.OAuthClientAuthPost, AuthorizePath: "/o/v2/auth"})
		DeferCleanup(p.Close)
		n := oauthtest.NewNetwork(p)
		q := url.Values{"response_type": {"code"}, "client_id": {"client-a"}, "redirect_uri": {"https://localai.example.test/cb"}, "scope": {"read"},
			"state": {"s"}, "code_challenge": {"x"}, "code_challenge_method": {"S256"}}
		back, err := n.Authorize(ctx, "https://"+host+"/o/v2/auth?"+q.Encode())
		Expect(err).NotTo(HaveOccurred())
		Expect(back.Query().Get("code")).NotTo(BeEmpty())
		_, err = n.Authorize(ctx, "https://"+host+"/authorize?"+q.Encode())
		Expect(err).To(HaveOccurred(), "the default path is not served when another is configured")
	})

	It("trades a code for the verifier it was issued for, with the client authentication it requires", func() {
		p := oauthtest.New(oauthtest.Config{Host: host, ClientID: "client-a", ClientSecret: "secret", ClientAuth: contract.OAuthClientAuthBasic})
		DeferCleanup(p.Close)
		n := oauthtest.NewNetwork(p)
		client := n.TokenClient()

		_, err := client.Exchange(ctx, desc(contract.OAuthClientAuthBasic), oauthtoken.Credentials{ID: "client-a", Secret: "secret"}, login(n, "v1"), "wrong-verifier", "https://localai.example.test/cb")
		Expect(err).To(MatchError(oauthtoken.ErrInvalidGrant))
		_, err = client.Exchange(ctx, desc(contract.OAuthClientAuthPost), oauthtoken.Credentials{ID: "client-a", Secret: "secret"}, login(n, "v2"), "v2", "https://localai.example.test/cb")
		Expect(err).To(MatchError(oauthtoken.ErrInvalidClient), "the secret in the form, where the service wants basic")
		tok, err := client.Exchange(ctx, desc(contract.OAuthClientAuthBasic), oauthtoken.Credentials{ID: "client-a", Secret: "secret"}, login(n, "v3"), "v3", "https://localai.example.test/cb")
		Expect(err).NotTo(HaveOccurred())
		Expect(tok.Refresh).NotTo(BeEmpty())
		auths := []string{}
		for _, c := range p.Calls() {
			auths = append(auths, c.Auth)
		}
		Expect(auths).To(Equal([]string{oauthtest.SeenBasic, oauthtest.SeenPost, oauthtest.SeenBasic}))
		Expect(p.Tokens.Load()).To(BeEquivalentTo(3))
	})

	It("sends the person back with access_denied when they decline", func() {
		p := oauthtest.New(oauthtest.Config{Host: host, ClientID: "client-a", ClientAuth: contract.OAuthClientAuthNone})
		DeferCleanup(p.Close)
		p.Set(func(p *oauthtest.Provider) { p.Deny = true })
		n := oauthtest.NewNetwork(p)
		back, err := n.Authorize(ctx, "https://"+host+"/authorize?"+url.Values{"response_type": {"code"}, "client_id": {"client-a"}, "redirect_uri": {"https://localai.example.test/cb"},
			"state": {"s"}, "code_challenge": {"c"}, "code_challenge_method": {"S256"}}.Encode())
		Expect(err).NotTo(HaveOccurred())
		Expect(back.Query().Get("error")).To(Equal("access_denied"))
		Expect(back.Query().Get("code")).To(BeEmpty())
	})

	It("rotates the refresh token and refuses the used one", func() {
		p := oauthtest.New(oauthtest.Config{Host: host, ClientID: "client-a", ClientAuth: contract.OAuthClientAuthNone})
		DeferCleanup(p.Close)
		p.Set(func(p *oauthtest.Provider) { p.Rotate = true })
		n := oauthtest.NewNetwork(p)
		cred := oauthtoken.Credentials{ID: "client-a"}
		tok, err := n.TokenClient().Exchange(ctx, desc(contract.OAuthClientAuthNone), cred, login(n, "v"), "v", "https://localai.example.test/cb")
		Expect(err).NotTo(HaveOccurred())
		next, err := n.TokenClient().Refresh(ctx, desc(contract.OAuthClientAuthNone), cred, tok.Refresh)
		Expect(err).NotTo(HaveOccurred())
		Expect(next.Refresh).NotTo(Equal(tok.Refresh))
		_, err = n.TokenClient().Refresh(ctx, desc(contract.OAuthClientAuthNone), cred, tok.Refresh)
		Expect(err).To(MatchError(oauthtoken.ErrInvalidGrant))
	})
})

package main

import (
	"archive/tar"
	"bytes"
	"context"
	"io"
	"os"
	"path/filepath"
	"testing"

	v1 "github.com/google/go-containerregistry/pkg/v1"
	"github.com/google/go-containerregistry/pkg/v1/empty"
	"github.com/google/go-containerregistry/pkg/v1/layout"
	"github.com/google/go-containerregistry/pkg/v1/mutate"
	"github.com/google/go-containerregistry/pkg/v1/tarball"
	"github.com/mudler/LocalAI/addons/sandbox/internal/sandbox/ociimage"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestOcipatch(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Sandbox ocipatch Suite")
}

func mustLayer() v1.Layer {
	var buf bytes.Buffer
	tw := tar.NewWriter(&buf)
	Expect(tw.WriteHeader(&tar.Header{Name: "etc/os", Typeflag: tar.TypeReg, Mode: 0o644, Size: 2})).To(Succeed())
	_, _ = tw.Write([]byte("ok"))
	_ = tw.Close()
	l, err := tarball.LayerFromOpener(func() (io.ReadCloser, error) { return io.NopCloser(bytes.NewReader(buf.Bytes())), nil })
	Expect(err).NotTo(HaveOccurred())
	return l
}

var _ = Describe("ocipatch", func() {
	It("adds a file on top", func() {
		base := filepath.Join(GinkgoT().TempDir(), "base")
		p, err := layout.Write(base, empty.Index)
		Expect(err).NotTo(HaveOccurred())
		img, err := mutate.AppendLayers(empty.Image, mustLayer())
		Expect(err).NotTo(HaveOccurred())
		Expect(p.AppendImage(img)).To(Succeed())
		src := filepath.Join(GinkgoT().TempDir(), "agent")
		Expect(os.WriteFile(src, []byte("new agent"), 0o755)).To(Succeed())
		out := filepath.Join(GinkgoT().TempDir(), "out")
		ref, err := patch(base, out, []string{"usr/sbin/agent=" + src})
		Expect(err).NotTo(HaveOccurred())
		var found string
		_, _, err = ociimage.PrepareTar(context.Background(), GinkgoT().TempDir(), ref, func(r io.Reader, _ string) error {
			tr := tar.NewReader(r)
			for {
				h, err := tr.Next()
				if err == io.EOF {
					return nil
				}
				if err != nil {
					return err
				}
				if h.Name == "usr/sbin/agent" {
					b, _ := io.ReadAll(tr)
					found = string(b)
				}
			}
		})
		Expect(err).NotTo(HaveOccurred())
		Expect(found).To(Equal("new agent"))
		fresh := func() string { return filepath.Join(GinkgoT().TempDir(), "out") }
		for _, bad := range []string{"/abs=x", "../up=x", "a/../b=x", "a//b=x", "./a=x", "..=x"} {
			_, err := patch(base, fresh(), []string{bad})
			Expect(err).To(MatchError(ContainSubstring("-add")), "-add %q", bad)
		}
		// An existing -out, or -out equal to -in, is refused: a second manifest
		// would be appended to the existing layout.
		_, err = patch(base, out, []string{"usr/sbin/agent=" + src})
		Expect(err).To(MatchError(ContainSubstring("exists")), "existing -out")
		_, err = patch(base, base, []string{"usr/sbin/agent=" + src})
		Expect(err).To(MatchError(ContainSubstring("same as -in")), "-out equal to -in")
	})

	// The patched image keeps the platform of the source descriptor, and an
	// image without one stays without one (no platform is invented).
	It("keeps the source platform", func() {
		for _, want := range []*v1.Platform{
			{OS: "linux", Architecture: "arm64"},
			nil,
		} {
			base := filepath.Join(GinkgoT().TempDir(), "base")
			p, err := layout.Write(base, empty.Index)
			Expect(err).NotTo(HaveOccurred())
			img, err := mutate.AppendLayers(empty.Image, mustLayer())
			Expect(err).NotTo(HaveOccurred())
			var opts []layout.Option
			if want != nil {
				opts = append(opts, layout.WithPlatform(*want))
			}
			Expect(p.AppendImage(img, opts...)).To(Succeed())
			src := filepath.Join(GinkgoT().TempDir(), "agent")
			Expect(os.WriteFile(src, []byte("new agent"), 0o755)).To(Succeed())
			out := filepath.Join(GinkgoT().TempDir(), "out")
			_, err = patch(base, out, []string{"usr/sbin/agent=" + src})
			Expect(err).NotTo(HaveOccurred())
			idx, err := layout.ImageIndexFromPath(out)
			Expect(err).NotTo(HaveOccurred())
			m, err := idx.IndexManifest()
			Expect(err).NotTo(HaveOccurred())
			Expect(m.Manifests).To(HaveLen(1))
			got := m.Manifests[0].Platform
			if want == nil {
				Expect(got).To(BeNil(), "platform invented")
			} else {
				Expect(got).NotTo(BeNil())
				Expect(got.OS).To(Equal(want.OS))
				Expect(got.Architecture).To(Equal(want.Architecture))
			}
		}
	})
})

package gallery

import (
	"context"
	"sync/atomic"

	"github.com/mudler/LocalAI/core/config"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

// expireOCIGalleryCache makes every unpacked gallery artifact stale for the
// rest of the spec, so the next fetch goes back to the registry the way it
// would an hour later.
func expireOCIGalleryCache() {
	GinkgoHelper()
	original := ociGalleryCacheTTL
	ociGalleryCacheTTL = 0
	DeferCleanup(func() { ociGalleryCacheTTL = original })
}

var _ = Describe("oci:// gallery caches and the verification policy", func() {
	const index = "- name: acme-model\n"

	loose := &config.GalleryVerification{
		Issuer:        "https://token.actions.githubusercontent.com",
		IdentityRegex: "^https://github.com/acme/.*$",
	}
	tightened := &config.GalleryVerification{
		Issuer:           "https://token.actions.githubusercontent.com",
		IdentityRegex:    "^https://github.com/acme/.*$",
		SourceRepository: "https://github.com/acme/gallery",
	}

	BeforeEach(resetGalleryFailures)

	// countingVerifier stubs the signature check: it counts the calls and
	// refuses any policy the refuse func rejects.
	countingVerifier := func(refuse func(*config.GalleryVerification) bool) *atomic.Int64 {
		GinkgoHelper()
		var calls atomic.Int64
		stubGalleryVerifier(func(_ context.Context, p *config.GalleryVerification, _ string) error {
			calls.Add(1)
			if refuse(p) {
				return errNoGallerySignature
			}
			return nil
		})
		return &calls
	}

	It("fetches and verifies again when the policy changes", func() {
		srv, requests, _ := ociRegistry()
		url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
			{title: "index.yaml", body: index},
		})
		calls := countingVerifier(func(*config.GalleryVerification) bool { return false })
		base := tempModelsDir()

		_, _, err := fetchGalleryIndex(context.Background(),
			config.Gallery{URL: url, Name: "acme", Verification: loose}, base, false)
		Expect(err).ToNot(HaveOccurred())
		Expect(calls.Load()).To(Equal(int64(1)))

		resetCounters(requests)
		body, _, err := fetchGalleryIndex(context.Background(),
			config.Gallery{URL: url, Name: "acme", Verification: tightened}, base, false)
		Expect(err).ToNot(HaveOccurred())
		Expect(string(body)).To(Equal(index))
		Expect(calls.Load()).To(Equal(int64(2)), "content verified under the old policy was reused under the new one")
		Expect(requests.Load()).ToNot(BeZero(), "the registry was not contacted after the policy changed")
	})

	It("does not serve content verified under the old policy when the new one refuses it", func() {
		srv, _, _ := ociRegistry()
		url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
			{title: "index.yaml", body: index},
		})
		countingVerifier(func(p *config.GalleryVerification) bool { return p.SourceRepository != "" })
		base := tempModelsDir()

		_, _, err := fetchGalleryIndex(context.Background(),
			config.Gallery{URL: url, Name: "acme", Verification: loose}, base, false)
		Expect(err).ToNot(HaveOccurred())

		body, served, err := fetchGalleryIndex(context.Background(),
			config.Gallery{URL: url, Name: "acme", Verification: tightened}, base, false)
		Expect(err).To(HaveOccurred(), "served %q from %q", string(body), served)
		Expect(err.Error()).To(ContainSubstring("signature"))
	})

	It("does not fall back to the last known good copy after a verification failure", func() {
		srv, _, _ := ociRegistry()
		url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
			{title: "index.yaml", body: index},
		})
		var refuse atomic.Bool
		countingVerifier(func(*config.GalleryVerification) bool { return refuse.Load() })
		base := tempModelsDir()
		g := config.Gallery{URL: url, Name: "acme", Verification: loose}

		_, _, err := fetchGalleryIndex(context.Background(), g, base, false)
		Expect(err).ToNot(HaveOccurred())
		Expect(galleryCachePath(base, url, loose)).To(BeARegularFile())

		// The publisher's artifact now fails the same policy, for example
		// because it was re-signed by an identity the policy does not trust.
		expireOCIGalleryCache()
		refuse.Store(true)

		body, served, err := fetchGalleryIndex(context.Background(), g, base, false)
		Expect(err).To(HaveOccurred(), "served %q from %q", string(body), served)
		Expect(err.Error()).To(ContainSubstring("signature"))
	})

	It("does not serve an unverified copy once strict integrity is on", func() {
		srv, _, _ := ociRegistry()
		url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
			{title: "index.yaml", body: index},
		})
		base := tempModelsDir()
		g := config.Gallery{URL: url, Name: "acme"}

		_, _, err := fetchGalleryIndex(context.Background(), g, base, false)
		Expect(err).ToNot(HaveOccurred())

		body, served, err := fetchGalleryIndex(context.Background(), g, base, true)
		Expect(err).To(HaveOccurred(), "served %q from %q", string(body), served)
		Expect(err.Error()).To(ContainSubstring("verification"))
	})

	Context("when the registry is unreachable", func() {
		It("falls back to a copy verified under the same policy", func() {
			srv, _, _ := ociRegistry()
			url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
				{title: "index.yaml", body: index},
			})
			countingVerifier(func(*config.GalleryVerification) bool { return false })
			base := tempModelsDir()
			g := config.Gallery{URL: url, Name: "acme", Verification: loose}

			_, _, err := fetchGalleryIndex(context.Background(), g, base, false)
			Expect(err).ToNot(HaveOccurred())

			expireOCIGalleryCache()
			srv.Close()

			body, served, err := fetchGalleryIndex(context.Background(), g, base, false)
			Expect(err).ToNot(HaveOccurred())
			Expect(string(body)).To(Equal(index))
			Expect(served).To(Equal(galleryCachePath(base, url, loose)))
		})

		It("does not fall back to a copy verified under another policy", func() {
			srv, _, _ := ociRegistry()
			url := pushGalleryArtifact(srv.URL, "galleries/acme", galleryArtifactType, []ociGalleryFile{
				{title: "index.yaml", body: index},
			})
			countingVerifier(func(*config.GalleryVerification) bool { return false })
			base := tempModelsDir()

			_, _, err := fetchGalleryIndex(context.Background(),
				config.Gallery{URL: url, Name: "acme", Verification: loose}, base, false)
			Expect(err).ToNot(HaveOccurred())

			expireOCIGalleryCache()
			srv.Close()

			body, served, err := fetchGalleryIndex(context.Background(),
				config.Gallery{URL: url, Name: "acme", Verification: tightened}, base, false)
			Expect(err).To(HaveOccurred(), "served %q from %q", string(body), served)
