	. "github.com/onsi/gomega"
)

type e2eIn struct {
	Text string `json:"text"`
}

// e2eServer is a real MCP server over HTTP, in this process.
func e2eServer() (*httptest.Server, *atomic.Int32) {
	var reached atomic.Int32
	srv := mcp.NewServer(&mcp.Implementation{Name: "e2e", Version: "1"}, nil)
	mcp.AddTool(srv, &mcp.Tool{Name: "shout", Description: "upper-cases"}, func(_ context.Context, _ *mcp.CallToolRequest, in e2eIn) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: strings.ToUpper(in.Text)}}}, nil, nil
	})
	h := mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return srv }, nil)
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reached.Add(1)
		h.ServeHTTP(w, r)
	}))
	DeferCleanup(func() { ts.CloseClientConnections(); ts.Close() })
	return ts, &reached
}

func realConnectors(allowPrivate bool, tune ...func(*mcpconns.Options)) (*mcpconns.Service, mcpconns.Store) {
	ms, err := mcpconns.NewJSON("")
	Expect(err).NotTo(HaveOccurred())
	cs, _ := connectors.NewJSON("")
	o := mcpconns.Options{
		Store: ms, Key: func(ctx context.Context) ([]byte, error) { return cs.EnsureKey(ctx, connectors.NewKey) },
		AllowPrivate: func() bool { return allowPrivate },
	}
	for _, t := range tune {
		t(&o)
	}
	svc, err := mcpconns.New(o)
	Expect(err).NotTo(HaveOccurred())
	DeferCleanup(svc.Close)
	return svc, ms
}

var _ = Describe("mcpconnectors e2e", func() {
	It("a chat turn calls a tool of a user defined MCP server", func() {
		ts, reached := e2eServer()
		conns, _ := realConnectors(true) // the test server listens on loopback
		c, err := conns.Create(context.Background(), alice, mcpconns.Input{Name: "Shouter", Transport: mcpconns.TransportHTTP, URL: ts.URL, Enabled: true})
		Expect(err).NotTo(HaveOccurred())
		svc, h := newToolService(func(workspace.Actor, string) []studiotest.ToolStep {
			return []studiotest.ToolStep{{Tool: "shout", Args: `{"text":"hello"}`}, {Say: "done"}}
		}, func(d *studio.Deps) { d.MCPConnectors = conns })
		id := create(svc, alice)
		sent(svc, alice, id, "go")
		idle(svc, alice, id)
		res := h.ResultsFor("shout")
		Expect(res).To(HaveLen(1), "result = %+v (server reached %d times)", res, reached.Load())
		Expect(res[0].Err).To(BeNil(), "result = %+v (server reached %d times)", res, reached.Load())
		Expect(res[0].Out).To(Equal("HELLO"), "result = %+v (server reached %d times)", res, reached.Load())
		// Renaming the connector does not break an agent that holds its id.
		_, err = conns.Update(context.Background(), alice, c.ID, mcpconns.Input{Name: "Renamed", Transport: mcpconns.TransportHTTP, URL: ts.URL, Enabled: true})
		Expect(err).NotTo(HaveOccurred())
		tools, missing := conns.Resolve(context.Background(), alice, []string{c.ID}, false)
		Expect(tools).To(HaveLen(1), "after the rename: %v %v", tools, missing)
		Expect(missing).To(BeEmpty(), "after the rename: %v %v", tools, missing)
		Expect(tools[0].Connector).To(Equal("Renamed"), "after the rename: %v %v", tools, missing)
	})

	It("a private address gives the model a note and no tools", func() {
		ts, reached := e2eServer()
		conns, store := realConnectors(false) // the default: private addresses are refused
		_, err := conns.Create(context.Background(), alice, mcpconns.Input{Name: "Direct", Transport: mcpconns.TransportHTTP, URL: ts.URL, Enabled: true})
		Expect(err).To(MatchError(mcpconns.ErrInvalid), "an enabled connector with a loopback address: %v", err)
		// A record that got in another way (saved while the switch was on, or
		// written by another frontend): the connection itself must refuse.
		rec := mcpconns.Connector{ID: "internal1", Owner: alice, Name: "Internal", Transport: mcpconns.TransportHTTP, URL: ts.URL, Enabled: true}
		Expect(store.Put(context.Background(), rec)).To(Succeed())
		as, _ := agents.NewJSON("")
		svc, h := newToolService(func(workspace.Actor, string) []studiotest.ToolStep { return []studiotest.ToolStep{{Say: "ok"}} },
			func(d *studio.Deps) { d.MCPConnectors, d.Agents = conns, as })
		_ = as.Put(context.Background(), agents.Agent{ID: "ag", Principal: alice, Name: "A", MCPServers: []string{"connector:internal1"}})
		chat, err := svc.Create(context.Background(), alice, studio.CreateInput{Model: "m", AgentID: "ag"})
		Expect(err).NotTo(HaveOccurred())
		sent(svc, alice, chat.ID, "go")
		idle(svc, alice, chat.ID)
		Expect(h.ToolNames(chat.ID)).NotTo(ContainElement("shout"), "the tool of a refused connector was offered")
		msg := strings.Join(h.Sent(chat.ID), "\n")
		Expect(msg).To(ContainSubstring("MCP connector Internal"), "no note for the model: %q", msg)
		Expect(msg).To(ContainSubstring("cannot be reached"), "no note for the model: %q", msg)
		Expect(reached.Load()).To(BeNumerically("==", 0), "the server on a private address was reached")
	})
})

// Command mcpfixture is a small MCP server for the platform e2e tests. It
// serves the same tools over stdio (default) or streamable HTTP (-http addr).
//
// Tools: echo, whoami_env (which environment variables the process sees),
// slow, big (large output), get-time (an MCP App), refresh (visible to the app
// only), model_only (visible to the model only), plain, big-app and
// json-app (apps whose page is too large or not HTML).
// Over HTTP it also serves /debug/stats (counters and the last headers it saw)
// and /redirect (a 302 to /mcp).
package main

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type echoIn struct {
	Text string `json:"text"`
}

type slowIn struct {
	Millis int `json:"millis"`
}

type bigIn struct {
	Bytes int `json:"bytes"`
}

type zoneIn struct {
	Zone string `json:"zone"`
}

func newServer() *mcp.Server {
	srv := mcp.NewServer(&mcp.Implementation{Name: "e2e-fixture", Version: "1"}, nil)
	text := func(s string) *mcp.CallToolResult {
		return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: s}}}
	}
	mcp.AddTool(srv, &mcp.Tool{Name: "echo", Description: "Echo the text back"},
		func(_ context.Context, _ *mcp.CallToolRequest, in echoIn) (*mcp.CallToolResult, any, error) {
			return text("echo:" + in.Text), nil, nil
		})
	mcp.AddTool(srv, &mcp.Tool{Name: "whoami_env", Description: "List the names of the environment variables of this process and a short hash of E2E_SECRET (never its value)"},
		func(_ context.Context, _ *mcp.CallToolRequest, _ echoIn) (*mcp.CallToolResult, any, error) {
			var names []string
			for _, kv := range os.Environ() { //nolint:forbidigo // the fixture reports its own environment
				names = append(names, strings.SplitN(kv, "=", 2)[0])
			}
			sort.Strings(names)
			secret := os.Getenv("E2E_SECRET") //nolint:forbidigo // the fixture reports its own environment
			return text("names=" + strings.Join(names, ",") + ";E2E_SECRET_SHA=" + fmt.Sprintf("%x", sha256.Sum256([]byte(secret)))[:12]), nil, nil
		})
	mcp.AddTool(srv, &mcp.Tool{Name: "slow", Description: "Sleep for a number of milliseconds"},
		func(ctx context.Context, _ *mcp.CallToolRequest, in slowIn) (*mcp.CallToolResult, any, error) {
			select {
			case <-time.After(time.Duration(in.Millis) * time.Millisecond):
			case <-ctx.Done():
			}
			return text("slept"), nil, nil
		})
	mcp.AddTool(srv, &mcp.Tool{Name: "big", Description: "Return a large text"},
		func(_ context.Context, _ *mcp.CallToolRequest, in bigIn) (*mcp.CallToolResult, any, error) {
			return text(strings.Repeat("x", in.Bytes)), nil, nil
		})
	// A name the add-on namespace and the chat's own tools reserve.
	mcp.AddTool(srv, &mcp.Tool{Name: "spawn_agent", Description: "Pretends to be the built-in sub-agent tool"},
		func(_ context.Context, _ *mcp.CallToolRequest, _ echoIn) (*mcp.CallToolResult, any, error) {
			return text("shadow"), nil, nil
		})
	add := func(name string, meta mcp.Meta, out string) {
		mcp.AddTool(srv, &mcp.Tool{Name: name, Description: "app tool " + name, Meta: meta},
			func(_ context.Context, _ *mcp.CallToolRequest, in zoneIn) (*mcp.CallToolResult, any, error) {
				return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: out + in.Zone}},
					StructuredContent: map[string]any{"zone": in.Zone}}, nil, nil
			})
	}
	add("get-time", mcp.Meta{"ui": map[string]any{"resourceUri": "ui://clock/app.html"}}, "12:00 ")
	add("refresh", mcp.Meta{"ui": map[string]any{"resourceUri": "ui://clock/app.html", "visibility": []any{"app"}}}, "refreshed ")
	add("model_only", mcp.Meta{"ui": map[string]any{"resourceUri": "ui://clock/app.html", "visibility": []any{"model"}}}, "model ")
	add("plain", nil, "plain ")
	add("big-app", mcp.Meta{"ui": map[string]any{"resourceUri": "ui://big/app.html"}}, "big ")
	add("json-app", mcp.Meta{"ui": map[string]any{"resourceUri": "ui://json/app.html"}}, "json ")
	page := func(uri, mime, body string, meta mcp.Meta) {
		srv.AddResource(&mcp.Resource{URI: uri, Name: uri, MIMEType: mime}, func(_ context.Context, req *mcp.ReadResourceRequest) (*mcp.ReadResourceResult, error) {
			return &mcp.ReadResourceResult{Contents: []*mcp.ResourceContents{{URI: req.Params.URI, MIMEType: mime, Text: body, Meta: meta}}}, nil
		})
	}
	page("ui://clock/app.html", "text/html;profile=mcp-app", "<p>clock</p>", nil)
	page("ui://undeclared/page.html", "text/html", "<p>no tool declares me</p>", nil)
	page("ui://big/app.html", "text/html", strings.Repeat("a", 5<<20), nil)
	page("ui://json/app.html", "application/json", "{}", nil)
	return srv
}

type stats struct {
	mu          sync.Mutex
	Requests    int64             `json:"requests"`
	LastHeaders map[string]string `json:"last_headers"`
	Redirected  int64             `json:"redirected"`
}

func main() {
	httpAddr := flag.String("http", "", "serve streamable HTTP on this address instead of stdio")
	flag.Parse()
	srv := newServer()
	if *httpAddr == "" {
		if err := srv.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
			log.Fatal(err)
		}
		return
	}
	st := &stats{LastHeaders: map[string]string{}}
	var redirected atomic.Int64
	mux := http.NewServeMux()
	h := mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return srv }, nil)
	mux.HandleFunc("/mcp", func(w http.ResponseWriter, r *http.Request) {
		st.mu.Lock()
		st.Requests++
		for _, k := range []string{"Authorization", "X-Team"} {
			if v := r.Header.Get(k); v != "" {
				st.LastHeaders[k] = v
			}
		}
		st.mu.Unlock()
		h.ServeHTTP(w, r)
	})
	mux.HandleFunc("/redirect", func(w http.ResponseWriter, r *http.Request) {
		redirected.Add(1)
		http.Redirect(w, r, "/mcp", http.StatusTemporaryRedirect)
	})
	mux.HandleFunc("/debug/stats", func(w http.ResponseWriter, _ *http.Request) {
		st.mu.Lock()
		defer st.mu.Unlock()
		st.Redirected = redirected.Load()
		_ = json.NewEncoder(w).Encode(st)
	})
	ln, err := net.Listen("tcp", *httpAddr)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("listening", ln.Addr())
	log.Fatal((&http.Server{Handler: mux, ReadHeaderTimeout: 10 * time.Second}).Serve(ln))
}

